
import type { LiveActivityPresentation } from "@relo/notification-contracts";

export const dashboardSections = [
  "inbox", "inbox-notifications", "inbox-delivery",
  "connections-services", "connections-phones", "connections-clients",
  "testing", "account", "docs",
] as const;

export type DashboardSection = (typeof dashboardSections)[number];

export function dashboardSection(value: string | undefined): DashboardSection | null {
  if (!value) return "inbox";
  return dashboardSections.includes(value as DashboardSection) ? value as DashboardSection : null;
}

export function dashboardPageNumber(value: string | undefined): number {
  if (!value || !/^\d+$/.test(value)) return 1;
  const page = Number(value);
  return Number.isSafeInteger(page) && page > 0 ? page : 1;
}

export function dashboardReleaseIdentity(value: string | undefined): string {
  const configured = value?.trim();
  return configured && /^[A-Za-z0-9][A-Za-z0-9._+-]{0,63}$/.test(configured) ? configured : "dev";
}

export function dashboardProgressPresentationReplacement(
  presentation: LiveActivityPresentation,
  status: string,
  percent: number,
): LiveActivityPresentation {
  const value = Math.max(0,Math.min(1,percent/100));
  const content = { ...presentation.content,status };
  let updated = false;
  const components = presentation.components.map((component) => {
    if (component.type === "progress_bar") {
      updated = true;
      return { ...component,value };
    }
    if (component.type !== "steps") return component;
    updated = true;
    const position = percent >= 100 ? component.items.length
      : Math.min(component.items.length-1,Math.floor(Math.max(0,percent)/100*component.items.length));
    return { ...component,items: component.items.map((item,index) => ({ ...item,
      state: percent >= 100 || index < position ? "complete" as const
        : index === position ? "current" as const : "pending" as const })) };
  });
  if (!updated) throw new Error("This presentation does not support progress updates");
  return { ...presentation,content,components };
}

export function dashboardCurrentCommandReceipts(activity: {
  id?: unknown;
  sequence?: unknown;
  deviceReceipts?: unknown;
}): Array<Record<string,any>> {
  if (typeof activity.id !== "string" || !Array.isArray(activity.deviceReceipts)) return [];
  const sequence = Number(activity.sequence);
  if (!Number.isFinite(sequence)) return [];
  return activity.deviceReceipts.filter((receipt): receipt is Record<string,any> =>
    Boolean(receipt) && typeof receipt === "object"
      && typeof receipt.eventId === "string"
      && typeof receipt.device?.id === "string"
      && receipt.activityId === activity.id
      && Number(receipt.sequence) === sequence);
}

export function renderDashboardActivityReceipt(
  root: { querySelector(selector: string): { textContent: string | null } | null } | null,
  activity: { id?: unknown; sequence?: unknown; deviceReceipts?: unknown },
): { expected: number; confirmed: number } {
  const receipts = dashboardCurrentCommandReceipts(activity);
  const confirmed = receipts.filter((receipt) => receipt.receivedAt).length;
  const node = root?.querySelector("[data-activity-receipt]");
  if (node) {
    node.textContent = receipts.length
      ? `${confirmed}/${receipts.length} exact event receipt(s) for sequence ${activity.sequence}`
        + (confirmed === receipts.length ? " confirmed by phone." : " remain unconfirmed.")
      : "No exact event receipt is expected for the current sequence.";
  }
  return { expected: receipts.length,confirmed };
}

export function dashboardInteractionResponseText(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "object" && typeof (value as { response?: unknown }).response === "string") {
    return (value as { response: string }).response;
  }
  return "";
}

export function renderDashboardActivityInteraction(
  root: { querySelector(selector: string): { textContent: string | null } | null } | null,
  activity: { interaction?: Record<string,any> | null },
): string {
  const node = root?.querySelector("[data-activity-interaction]");
  const receipt = activity.interaction;
  if (!receipt) {
    if (node) node.textContent = "No response requested for this run.";
    return "No response requested for this run.";
  }
  const parts = [receipt.kind,receipt.state];
  if (receipt.action) parts.push(`action ${receipt.action}`);
  const response = dashboardInteractionResponseText(receipt.response);
  if (response) parts.push(`value ${response}`);
  if (receipt.device?.name) parts.push(`device ${receipt.device.name}`);
  if (receipt.respondedAt) parts.push(`responded ${new Date(receipt.respondedAt).toISOString()}`);
  const text = parts.join(" | ");
  if (node) node.textContent = text;
  return text;
}

export function renderDashboardServerAcceptedUpdate(
  root: any,
  activity: { id: string; state: string; status: string; progress: number; sequence: number },
): boolean {
  if (!root || root.dataset?.activityId !== activity.id) return false;
  const percent = Math.round(activity.progress*100);
  root.dataset.state = activity.state;
  const state = root.querySelector("[data-activity-state]");
  const server = root.querySelector("[data-activity-server]");
  const receipt = root.querySelector("[data-activity-receipt]");
  const progress = root.querySelector("#activity-progress");
  const progressOutput = root.querySelector("#activity-progress-output");
  if (state) {
    state.dataset.state = activity.state;
    state.textContent = activity.state;
  }
  if (server) server.textContent = `${activity.status} | sequence ${activity.sequence} | ${percent}%`;
  if (receipt) receipt.textContent = `Phone confirmation for update sequence ${activity.sequence} is pending.`;
  if (progress) progress.value = String(percent);
  if (progressOutput) progressOutput.textContent = `${percent}%`;
  root.querySelectorAll("[data-preview-progress]").forEach((node: any) => {
    node.dataset.previewProgress = String(percent);
  });
  root.querySelectorAll("[data-preview-status]").forEach((node: any) => { node.textContent = activity.status; });
  root.querySelectorAll("[data-preview-percent],[data-preview-island-trailing]")
    .forEach((node: any) => { node.textContent = `${percent}%`; });
  return true;
}

export function updateDashboardActivityControlState(
  root: any,
  state: string,
  receiptState: { expected: number; confirmed: number },
): { terminal: boolean; recoveryUnavailable: boolean } {
  const terminal = state !== "active";
  root?.querySelectorAll("input,[data-workbench-action]").forEach((control: any) => {
    control.disabled = terminal;
    control.dataset.terminal = String(terminal);
  });
  const recovery = root?.querySelector("[data-receipt-recovery]");
  const recoveryUnavailable = receiptState.expected === receiptState.confirmed;
  if (recovery) {
    recovery.disabled = recoveryUnavailable;
    recovery.dataset.terminal = String(recoveryUnavailable);
  }
  return { terminal,recoveryUnavailable };
}

export function renderDashboardPager(input: {
  path: string;
  page: number;
  pageSize: number;
  total: number;
  query?: Record<string,string | undefined>;
}): string {
  const pageCount = Math.max(1,Math.ceil(input.total/input.pageSize));
  const page = Math.min(Math.max(1,input.page),pageCount);
  if (pageCount === 1) return `<p class="pagination-summary" data-slot="pagination-summary">${input.total} total</p>`;
  const href = (nextPage: number) => {
    const params = new URLSearchParams();
    for (const [key,value] of Object.entries(input.query ?? {})) if (value) params.set(key,value);
    params.set("page",String(nextPage));
    return `${input.path}?${params.toString()}`;
  };
  const previous = page > 1
    ? `<a class="button secondary" rel="prev" href="${escape(href(page-1))}">Previous</a>`
    : `<span class="button secondary disabled" aria-disabled="true">Previous</span>`;
  const next = page < pageCount
    ? `<a class="button secondary" rel="next" href="${escape(href(page+1))}">Next</a>`
    : `<span class="button secondary disabled" aria-disabled="true">Next</span>`;
  return `<nav class="pagination" data-slot="pagination" aria-label="History pages">${previous}<span>Page ${page} of ${pageCount} · ${input.total} total</span>${next}</nav>`;
}

export function renderOneTimeServiceSecretPanel(): string {
  return `<section id="service-secret-panel" class="secret-panel" data-slot="alert" role="region" aria-labelledby="service-secret-heading" hidden><h3 id="service-secret-heading">Secret webhook created</h3><p>The raw URL is never rendered. Copy it to the clipboard now; dismissing clears it from browser memory.</p><div class="actions"><button id="copy-service-secret" data-slot="button" type="button">Copy secret URL</button><button id="dismiss-service-secret" class="secondary" data-slot="button" type="button">Dismiss</button></div><p id="service-secret-status" class="muted" role="status" aria-live="polite"></p></section>`;
}

const navigation: Array<{ label: string; items: Array<[DashboardSection,string,string]> }> = [
  { label: "Operate", items: [
    ["inbox","Inbox","/dashboard"],
    ["connections-services","Connections","/dashboard/connections/services"],
    ["testing","Test Lab","/dashboard/testing"],
  ] },
  { label: "System", items: [
    ["account","Account","/dashboard/account"],
    ["docs","Documentation","/dashboard/docs"],
  ] },
];

export function renderDashboardTabs(input: {
  label: string;
  active: string;
  tabs: Array<{ id: string; label: string; href: string; count?: number }>;
}): string {
  return `<nav class="route-tabs" data-slot="tabs-list" aria-label="${escape(input.label)}">${input.tabs.map((tab) => {
    const current = tab.id === input.active ? ' aria-current="page"' : "";
    const count = tab.count === undefined ? "" : `<span class="route-tab-count" data-slot="badge">${tab.count}</span>`;
    return `<a class="route-tab" data-slot="tabs-trigger" href="${escape(tab.href)}"${current}>${escape(tab.label)}${count}</a>`;
  }).join("")}</nav>`;
}

function escape(value: string): string {
  return value.replace(/[&<>'"]/g, (character) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;",
  })[character]!);
}

export function renderDocument(title: string, content: string): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>${escape(title)} · Relo</title><link rel="stylesheet" href="/assets/relo-dashboard.css"><script src="/assets/relo-dashboard.js" defer></script></head><body><main class="public-main" data-slot="public-content" id="main-content">${content}</main></body></html>`;
}

export function renderDashboardDocument(input: {
  active: DashboardSection;
  title: string;
  eyebrow: string;
  description: string;
  content: string;
  releaseIdentity: string;
  account: { initial: string; name: string; email: string };
}): string {
  const nav = navigation.map((group) => `<div class="nav-group" data-slot="sidebar-group"><div class="nav-label" data-slot="sidebar-group-label">${group.label}</div>${group.items.map(([section,label,href]) => {
    const current = input.active === section
      || (section === "inbox" && input.active.startsWith("inbox-"))
      || (section === "connections-services" && input.active.startsWith("connections-"))
      ? ' aria-current="page"' : "";
    return `<a class="nav-item" data-slot="sidebar-menu-button" href="${href}"${current}>${label}</a>`;
  }).join("")}</div>`).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>${escape(input.title)} · Relo</title><link rel="stylesheet" href="/assets/relo-dashboard.css"><script src="/assets/relo-dashboard.js" defer></script></head><body class="dashboard-body" data-slot="dashboard-root"><!-- IMPECCABLE-DIRECTION seed=neon-shadcn-operate | THESIS: A precise control plane for messaging operations. | OWN-WORLD: Black infrastructure surfaces, compact data, and one restrained teal action color. | STORY: Orient, inspect, act, then verify. | FIRST VIEWPORT: Navigation, page purpose, system status, and primary work are immediately legible. | FORM: Server-native shadcn contracts with square cards, crisp borders, and mono technical data. | FINISH: Every state remains readable, keyboard-safe, responsive, and free of decorative noise. --><a class="skip-link" data-slot="skip-link" href="#main-content">Skip to content</a><button class="mobile-nav-toggle" data-slot="sidebar-trigger" id="mobile-nav-toggle" type="button" aria-expanded="false" aria-controls="dashboard-sidebar"><span class="menu-icon" aria-hidden="true"><i></i><i></i><i></i></span><span>Menu</span></button><div class="sidebar-backdrop" data-slot="sidebar-overlay" id="sidebar-backdrop" hidden></div><aside class="sidebar" data-slot="sidebar" id="dashboard-sidebar" aria-label="Dashboard navigation"><a class="brand-lockup" data-slot="sidebar-header" href="/dashboard"><span class="brand-mark" aria-hidden="true">R</span><span><strong>Relo</strong><small>Control plane</small></span></a><nav aria-label="Primary">${nav}</nav><div class="sidebar-release" data-slot="sidebar-footer" data-release-identity="${escape(input.releaseIdentity)}" aria-label="Running release ${escape(input.releaseIdentity)}"><span>Release</span><strong>${escape(input.releaseIdentity)}</strong></div><div class="sidebar-account" data-slot="sidebar-account"><span class="avatar" aria-hidden="true">${escape(input.account.initial)}</span><span class="account-copy"><strong>${escape(input.account.name)}</strong><small>${escape(input.account.email)}</small></span><button id="sign-out" class="icon-button" data-slot="button" type="button">Sign out</button></div></aside><main class="dashboard-main" data-slot="dashboard-content" id="main-content" tabindex="-1"><header class="page-header" data-slot="page-header"><div><h1>${escape(input.title)}</h1><p>${escape(input.description)}</p></div></header><p id="dashboard-message" class="notice" data-slot="status-message" role="status" aria-live="polite" aria-atomic="true"></p>${input.content}</main></body></html>`;
}

